import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Short fight sounds, generated by `tool/generate_sounds.py`.
enum Cue { bossBeat, tap, perfect, miss, win, lose, count }

/// Plays fight cues. Behind an interface so tests stay silent.
abstract class FightSounds {
  Future<void> play(Cue cue);
  Future<void> dispose();
}

/// Low-latency pools (Android SoundPool), one per cue, loaded on first use.
class PooledFightSounds implements FightSounds {
  final _pools = <Cue, Future<AudioPool>>{};

  static String _file(Cue cue) => switch (cue) {
    Cue.bossBeat => 'boss_beat',
    Cue.tap => 'tap',
    Cue.perfect => 'perfect',
    Cue.miss => 'miss',
    Cue.win => 'win',
    Cue.lose => 'lose',
    Cue.count => 'count',
  };

  /// Loads every cue up front so the first beat is not late.
  Future<void> preload() => Future.wait(Cue.values.map(_pool));

  Future<AudioPool> _pool(Cue cue) => _pools[cue] ??= AudioPool.createFromAsset(
    path: 'sounds/${_file(cue)}.wav',
    maxPlayers: 4,
  );

  @override
  Future<void> play(Cue cue) async {
    try {
      await (await _pool(cue)).start();
    } catch (error) {
      // A missing sound must never break a fight.
      debugPrint('Sound $cue failed: $error');
    }
  }

  @override
  Future<void> dispose() async {
    for (final pool in _pools.values) {
      await (await pool).dispose();
    }
    _pools.clear();
  }
}

class SilentFightSounds implements FightSounds {
  @override
  Future<void> play(Cue cue) async {}

  @override
  Future<void> dispose() async {}
}

final fightSoundsProvider = Provider<FightSounds>((ref) {
  final sounds = PooledFightSounds();
  ref.onDispose(sounds.dispose);
  return sounds;
});

/// A light vibration for each beat (no permission needed).
void beatHaptic() => HapticFeedback.lightImpact();
